use derive_more :: Display ; use derive_setters :: Setters ; use serde :: { Deserialize , Serialize } ; use uuid :: Uuid ; use crate :: WorkspaceId ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Progress events emitted during workspace indexing"] # [derive (Debug , Clone , PartialEq)] pub enum SyncProgress { # [doc = " Sync operation is starting"] Starting , # [doc = " A new workspace was created on the server"] WorkspaceCreated { # [doc = " The ID of the newly created workspace"] workspace_id : WorkspaceId , } , # [doc = " Discovering files in the directory"] DiscoveringFiles { # [doc = " ID of the current workspace"] workspace_id : WorkspaceId , # [doc = " Path being scanned"] path : std :: path :: PathBuf , } , # [doc = " Files have been discovered in the directory"] FilesDiscovered { # [doc = " Total number of files found"] count : usize , } , # [doc = " Comparing local files with server state"] ComparingFiles { # [doc = " Number of remote files in the workspace"] remote_files : usize , # [doc = " Number of local files being compared"] local_files : usize , } , # [doc = " Diff computed showing breakdown of changes"] DiffComputed { # [doc = " Number of files added (new files)"] added : usize , # [doc = " Number of files deleted (orphaned on server)"] deleted : usize , # [doc = " Number of files modified (changed files)"] modified : usize , } , # [doc = " Syncing files (deleting outdated + uploading new/changed)"] Syncing { # [doc = " Current progress"] current : usize , # [doc = " Total number of files to sync"] total : usize , } , # [doc = " Sync operation completed successfully"] Completed { # [doc = " Total number of files in the workspace"] total_files : usize , # [doc = " Number of files that were uploaded (changed or new)"] uploaded_files : usize , # [doc = " Number of files that failed to sync"] failed_files : usize , } , }